import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { MessageSquare, Send } from 'lucide-react'
import { useAuth } from '../lib/auth'
import { navigate } from '../lib/router'
import { cx } from '../lib/utils'
import posthog, { isPostHogEnabled } from '../lib/posthog'

const MAX_LEN = 500

/** Rank thresholds — keep in sync with rankFor() in api/comments/index.ts */
const RANKS = [
  { n: 'Rookie', min: 0 },
  { n: 'Beginner', min: 50 },
  { n: 'Reader', min: 150 },
  { n: 'Active', min: 400 },
  { n: 'Veteran', min: 1000 },
  { n: 'Mythic', min: 2500 },
]

function rankFor(xp: number) {
  let l = 0
  for (let i = 0; i < RANKS.length; i++) if (xp >= RANKS[i].min) l = i
  const rank = RANKS[l]
  const next = RANKS[l + 1] ?? null
  return { name: rank.n, level: l, min: rank.min, next }
}

interface CommentItem {
  id: string
  u: string
  t: number
  x: string
  sp?: boolean
  rTo?: string
  likes?: string[]
  rk?: { n: string; l: number }
}

interface MeInfo {
  username: string
  xp: number
  n: string
  l: number
}

/** Relative timestamp. */
function timeAgo(t: number): string {
  const s = Math.floor((Date.now() - t) / 1000)
  if (s < 60) return 'just now'
  if (s < 3600) return `${Math.floor(s / 60)}m ago`
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`
  if (s < 86400 * 30) return `${Math.floor(s / 86400)}d ago`
  return new Date(t).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
}

/** Safe rich text: escape everything, then apply the light markup the
 *  composer toolbar emits (bold, italic, spoilers, images, bare links,
 *  @mentions). No raw HTML is ever injected. */
function renderRich(text: string): string {
  const esc: Record<string, string> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }
  let h = text.replace(/[&<>"']/g, (m) => esc[m])
  const images: string[] = []
  // pull image URLs out first so the link pass doesn't wrap them
  h = h.replace(/(https?:\/\/[^\s<]+?\.(?:png|jpe?g|gif|webp)(?:\?[^\s]*)?)/gi, (m0) => {
    images.push(
      `<img src="${m0}" alt="image" loading="lazy" decoding="async" referrerpolicy="no-referrer">`,
    )
    return `\u0000IMG${images.length - 1}\u0000`
  })
  // spoilers ||…|| (click to reveal — delegated handler below)
  h = h.replace(/\|\|([\s\S]+?)\|\|/g, (_m, inner) => `<span class="cmt-spoiler"><span>${inner}</span></span>`)
  // bold / italic
  h = h.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>')
  h = h.replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>')
  // mentions @name
  h = h.replace(/@([a-zA-Z0-9_-]{3,20})/g, '<span class="cmt-mention">@$1</span>')
  // remaining bare links (not already inside a tag)
  h = h.replace(/(^|[\s>])((?:https?:\/\/)[^\s<]+)/g, (_m, pre, url) => {
    if (/^https?:\/\//i.test(url) && !url.startsWith('http')) return _m
    return `${pre}<a href="${url}" target="_blank" rel="noopener nofollow">${url}</a>`
  })
  // restore images
  h = h.replace(/\u0000IMG(\d+)\u0000/g, (_m, i) => images[Number(i)] ?? '')
  return h
}

export default function Comments({
  type,
  threadKey,
  dark = false,
  heading = 'Comments',
}: {
  type: 'series' | 'chapter'
  threadKey: string
  dark?: boolean
  heading?: string
}) {
  const { user } = useAuth()
  const [comments, setComments] = useState<CommentItem[] | null>(null)
  const [me, setMe] = useState<MeInfo | null>(null)
  const [text, setText] = useState('')
  const [spoiler, setSpoiler] = useState(false)
  const [sort, setSort] = useState<'top' | 'new' | 'old'>('new')
  const [replyTo, setReplyTo] = useState<string | null>(null)
  const [liked, setLiked] = useState<Record<string, boolean>>({})
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [cooldown, setCooldown] = useState(0)
  const [spoilerHidden, setSpoilerHidden] = useState<Record<string, boolean>>({})
  const [activatedThread, setActivatedThread] = useState<string | null>(null)
  const taRef = useRef<HTMLTextAreaElement>(null)
  const rootRef = useRef<HTMLElement>(null)

  const card = dark ? 'border-onyx-line bg-onyx-2' : 'border-line bg-paper'
  const soft = dark ? 'text-white/60' : 'text-ink-soft'
  const faint = dark ? 'text-white/40' : 'text-ink-faint'
  const field = dark
    ? 'border-onyx-line bg-onyx text-white placeholder-white/30'
    : 'border-line-strong bg-paper text-ink placeholder-ink-faint'

  const load = useCallback(async () => {
    try {
      const res = await fetch(`/api/comments?type=${type}&key=${encodeURIComponent(threadKey)}`)
      if (!res.ok) throw new Error(String(res.status))
      const data = await res.json()
      setComments(data.comments ?? [])
      if (data.me) setMe(data.me)
    } catch {
      setComments([])
    }
  }, [type, threadKey])

  // Threads sit at the END of long series/chapter pages. Do not invoke the
  // comments function or Blob list() for visitors who never scroll there.
  // A generous root margin starts loading before the section is visible, so
  // users still see the thread without waiting. Browsers without
  // IntersectionObserver fall back to immediate loading.
  useEffect(() => {
    const el = rootRef.current
    if (!el || !('IntersectionObserver' in window)) {
      setActivatedThread(threadKey)
      return
    }
    const observer = new IntersectionObserver(
      (entries) => {
        if (!entries.some((entry) => entry.isIntersecting)) return
        setActivatedThread(threadKey)
        observer.disconnect()
      },
      { rootMargin: '700px 0px' },
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [threadKey])

  useEffect(() => {
    setComments(null)
    setError('')
    if (activatedThread === threadKey) void load()
  }, [activatedThread, load, threadKey])

  useEffect(() => {
    if (cooldown <= 0) return
    const t = setTimeout(() => setCooldown((s) => s - 1), 1000)
    return () => clearTimeout(t)
  }, [cooldown])

  // comments flagged as spoilers start hidden
  useEffect(() => {
    if (!comments) return
    setSpoilerHidden((cur) => {
      const next = { ...cur }
      for (const cc of comments) if (cc.sp && next[cc.id] === undefined) next[cc.id] = true
      return next
    })
  }, [comments])

  // delegated click handler: spoiler reveal
  const onBodyClick = useCallback((e: React.MouseEvent) => {
    const t = (e.target as HTMLElement).closest('.cmt-spoiler')
    if (t) t.classList.toggle('revealed')
  }, [])

  const wrapSelection = (before: string, after: string) => {
    const ta = taRef.current
    if (!ta) return
    const { selectionStart: s, selectionEnd: e, value } = ta
    const next = value.slice(0, s) + before + value.slice(s, e) + after + value.slice(e)
    setText(next.slice(0, MAX_LEN))
    requestAnimationFrame(() => {
      ta.focus()
      ta.selectionStart = s + before.length
      ta.selectionEnd = e + before.length
    })
  }

  const insertEmoji = (em: string) => {
    const ta = taRef.current
    const at = ta ? ta.selectionStart : text.length
    setText((text.slice(0, at) + em + text.slice(at)).slice(0, MAX_LEN))
  }

  const post = async (parent?: string) => {
    const clean = text.trim()
    if (!clean || busy) return
    setBusy(true)
    setError('')
    try {
      const res = await fetch('/api/comments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type, key: threadKey, text: clean, sp: spoiler, rTo: parent }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(data.error ?? 'Could not post your comment.')
        return
      }
      setComments((cur) => [...(cur ?? []), data.comment])
      if (data.me) setMe(data.me)
      if (isPostHogEnabled) {
        posthog.capture('comment_posted', {
          thread_type: type,
          is_reply: Boolean(parent),
          contains_spoiler: spoiler,
        })
      }
      setText('')
      setSpoiler(false)
      setReplyTo(null)
      setCooldown(15)
    } catch {
      setError('Network error — try again.')
    } finally {
      setBusy(false)
    }
  }

  const toggleLike = async (c: CommentItem) => {
    if (!user) return navigate('/account')
    try {
      const res = await fetch('/api/comments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'like', type, key: threadKey, id: c.id }),
      })
      const data = await res.json()
      if (!res.ok) return
      const likes = data.likes ?? []
      setComments((cur) => (cur ?? []).map((x) => (x.id === c.id ? { ...x, likes } : x)))
      const isNowLiked = likes.includes(user.username)
      setLiked((cur) => ({ ...cur, [c.id]: isNowLiked }))
      if (isNowLiked && isPostHogEnabled) posthog.capture('comment_liked', { thread_type: type })
    } catch {
      /* ignore */
    }
  }

  // group replies under their parents, then sort. Orphan replies (parent
  // briefly invisible to a fresh list, or a stale rTo) render as top-level.
  const visible = useMemo(() => {
    const all = comments ?? []
    const ids = new Set(all.map((c) => c.id))
    const tops = all.filter((c) => !c.rTo || !ids.has(c.rTo))
    const repliesOf = (id: string) =>
      all
        .filter((c) => c.rTo === id)
        .sort((a, b) => (sort === 'old' ? a.t - b.t : b.t - a.t))
    const likeN = (c: CommentItem) => c.likes?.length ?? 0
    let sorted = tops
    if (sort === 'top') sorted = [...tops].sort((a, b) => likeN(b) - likeN(a) || b.t - a.t)
    if (sort === 'new') sorted = [...tops].sort((a, b) => b.t - a.t)
    if (sort === 'old') sorted = [...tops].sort((a, b) => a.t - b.t)
    return sorted.map((c) => ({ c, replies: repliesOf(c.id) }))
  }, [comments, sort])

  const xpBar = me ? rankFor(me.xp) : null

  const RankChip = ({ n, l }: { n: string; l: number }) => (
    <span className={cx('rank-chip', `rank-${l}`)}>{l === 5 ? '✦ ' : ''}{n}</span>
  )

  const XpBar = ({ xp }: { xp: number }) => {
    const r = rankFor(xp)
    if (!r.next) return <div className={cx('text-[10px] font-semibold', faint)}>{xp} XP · MAX RANK</div>
    const span = r.next.min - r.min
    const pct = Math.min(100, Math.round(((xp - r.min) / span) * 100))
    return (
      <div className="mt-1 w-32">
        <div className={cx('h-1 w-full overflow-hidden rounded-full', dark ? 'bg-white/10' : 'bg-ink/10')}>
          <div className="h-full rounded-full bg-accent" style={{ width: `${pct}%` }} />
        </div>
        <div className={cx('mt-0.5 text-[10px] font-semibold', faint)}>
          {xp} / {r.next.min} XP → {r.next.n}
        </div>
      </div>
    )
  }

  const CommentBody = ({ x, id }: { x: string; id: string }) => {
    const hidden = spoilerHidden[id]
    return (
      <div
        className={cx('cmt-body mt-1 whitespace-pre-line break-words text-sm leading-relaxed', dark ? 'text-white/80' : 'text-ink-soft')}
        onClick={onBodyClick}
        dangerouslySetInnerHTML={{ __html: hidden ? '<em>Spoiler — tap to reveal</em>' : renderRich(x) }}
      />
    )
  }

  const renderComment = (c: CommentItem, replies: CommentItem[] = [], depth = 0) => {
    const isLiked = liked[c.id] ?? (user ? (c.likes ?? []).includes(user.username) : false)
    return (
      <li key={c.id} className={cx(depth > 0 && 'ml-8 border-l-2 pl-4', dark ? 'border-onyx-line' : 'border-line')}>
        <div className="flex items-start gap-3">
          <div
            className={cx(
              'flex h-9 w-9 shrink-0 select-none items-center justify-center rounded-full text-sm font-extrabold uppercase text-white',
              (c.rk?.l ?? 0) >= 5
                ? 'bg-gradient-to-br from-accent to-[#9e5bff]'
                : (c.rk?.l ?? 0) >= 3
                  ? 'bg-gradient-to-br from-[#8b5cf6] to-[#d95743]'
                  : // fixed dark circle — bg-ink flips LIGHT in the dark site
                    // theme (white initials on a light circle = invisible)
                    'bg-[#3a3a35]',
            )}
            aria-hidden
          >
            {c.u.slice(0, 1)}
          </div>
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
              <span className="text-sm font-bold">{c.u}</span>
              {c.rk && <RankChip n={c.rk.n} l={c.rk.l} />}
              <span className={cx('text-xs', faint)}>{timeAgo(c.t)}</span>
            </div>
            {c.rTo && (
              <div className="mt-1">
                <span className={cx('inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold', dark ? 'bg-white/10 text-white/70' : 'bg-ink/5 text-ink-soft')}>
                  ⤷ replying
                </span>
              </div>
            )}
            <CommentBody x={c.x} id={c.id} />
            <div className={cx('mt-1.5 flex items-center gap-3 text-xs font-semibold', faint)}>
              <button
                type="button"
                onClick={() => toggleLike(c)}
                className={cx('transition-colors hover:text-accent', isLiked && 'text-accent')}
              >
                👍 {c.likes?.length ?? 0}
              </button>
              <button type="button" onClick={() => setReplyTo(replyTo === c.id ? null : c.id)} className="transition-colors hover:text-accent">
                Reply
              </button>
            </div>

            {replyTo === c.id && user && (
              <div className="mt-2">
                <textarea
                  value={text}
                  onChange={(e) => setText(e.target.value.slice(0, MAX_LEN))}
                  placeholder={`Reply to ${c.u}…`}
                  rows={2}
                  className={cx('w-full resize-y rounded-[12px] border px-3 py-2 text-sm outline-none transition-colors focus:border-accent', field)}
                />
                <div className="mt-1.5 flex items-center justify-end gap-2">
                  <button type="button" onClick={() => setReplyTo(null)} className={cx('rounded-full px-3 py-1.5 text-xs font-bold', dark ? 'text-white/60 hover:text-white' : 'text-ink-faint hover:text-ink')}>
                    Cancel
                  </button>
                  <button
                    type="button"
                    onClick={() => post(c.id)}
                    disabled={busy || text.trim().length === 0}
                    className={cx(
                      'inline-flex items-center gap-1.5 rounded-full px-4 py-1.5 text-xs font-bold text-white transition-all',
                      busy || text.trim().length === 0 ? 'cursor-not-allowed bg-ink/10 text-ink-faint' : 'bg-accent hover:bg-accent-dark',
                    )}
                  >
                    <Send width={12} height={12} /> Reply
                  </button>
                </div>
              </div>
            )}

            {replies.length > 0 && (
              <ul className="mt-4 space-y-4">
                {replies.map((rc) => renderComment(rc, [], depth + 1))}
              </ul>
            )}
          </div>
        </div>
      </li>
    )
  }

  return (
    <section ref={rootRef} className={cx('min-h-24 rounded-[18px] border p-6 sm:p-8', card)}>
      <div className="mb-4 flex items-center gap-2">
        <MessageSquare width={18} height={18} className="text-accent" />
        <h3 className="text-lg font-extrabold tracking-tight">
          {heading}
          {comments && comments.length > 0 && (
            <span className={cx('ml-2 text-sm font-bold', faint)}>({comments.length})</span>
          )}
        </h3>
      </div>

      {/* Community guidelines banner */}
      <div className={cx('mb-4 flex items-center gap-2 rounded-[10px] border px-4 py-2.5 text-xs', dark ? 'border-onyx-line bg-onyx text-white/70' : 'border-line bg-paper-2 text-ink-soft')}>
        <span className="text-accent">▣</span>
        <span>
          Keep it clean — no spam, no NSFW. Tag spoilers with the{' '}
          <strong className={dark ? 'text-white' : 'text-ink'}>Spoiler</strong> toggle or wrap them in ||double bars||.
        </span>
      </div>

      {/* Post box */}
      {user ? (
        <div className={cx('rounded-[14px] border p-4', dark ? 'border-onyx-line bg-onyx' : 'border-line-strong bg-paper')}>
          <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
            <div className="flex items-center gap-2">
              <RankChip n={xpBar ? xpBar.name : 'Rookie'} l={xpBar ? xpBar.level : 0} />
              <span className={cx('text-xs', faint)}>as</span>
              <strong className={cx('text-sm', dark ? 'text-white' : 'text-ink')}>{user.username}</strong>
            </div>
            {xpBar && <XpBar xp={me!.xp} />}
          </div>
          <textarea
            ref={taRef}
            value={text}
            onChange={(e) => setText(e.target.value.slice(0, MAX_LEN))}
            placeholder={type === 'chapter' ? 'Share your thoughts on this chapter…' : 'Share your thoughts…'}
            rows={3}
            className={cx('w-full resize-y rounded-[12px] border px-4 py-3 text-sm outline-none transition-colors focus:border-accent', field)}
          />
          {/* formatting toolbar */}
          <div className="mt-2 flex flex-wrap items-center justify-between gap-2">
            <div className="flex items-center gap-1.5">
              <button type="button" onClick={() => wrapSelection('**', '**')} title="Bold" className={cx('h-8 w-8 rounded-[8px] border text-sm font-extrabold transition-colors hover:border-accent hover:text-accent', dark ? 'border-onyx-line text-white/80' : 'border-line text-ink-soft')}>
                B
              </button>
              <button type="button" onClick={() => wrapSelection('*', '*')} title="Italic" className={cx('h-8 w-8 rounded-[8px] border text-sm font-bold italic transition-colors hover:border-accent hover:text-accent', dark ? 'border-onyx-line text-white/80' : 'border-line text-ink-soft')}>
                I
              </button>
              <button type="button" onClick={() => wrapSelection('||', '||')} title="Spoiler" className={cx('h-8 rounded-[8px] border px-2 text-xs font-bold transition-colors hover:border-accent hover:text-accent', dark ? 'border-onyx-line text-white/80' : 'border-line text-ink-soft')}>
                Spoiler
              </button>
              {['🔥', '😂', '😭', '❤️', '👑', '✨', '💪', '🎉'].map((em) => (
                <button key={em} type="button" onClick={() => insertEmoji(em)} className={cx('h-8 w-8 rounded-[8px] text-base transition-colors hover:bg-ink/5', dark ? 'hover:bg-white/10' : '')}>
                  {em}
                </button>
              ))}
            </div>
            <button
              type="button"
              onClick={() => post(replyTo ?? undefined)}
              disabled={busy || cooldown > 0 || text.trim().length === 0}
              className={cx(
                'inline-flex items-center gap-2 rounded-full px-5 py-2 text-sm font-bold transition-all',
                busy || cooldown > 0 || text.trim().length === 0
                  ? 'cursor-not-allowed bg-ink/10 text-ink-faint'
                  : 'bg-accent text-white hover:bg-accent-dark',
              )}
            >
              <Send width={14} height={14} />{' '}
              {busy ? 'Posting…' : cooldown > 0 ? `Wait ${cooldown}s` : 'Post Comment'}
            </button>
          </div>
          <div className="mt-2 flex flex-wrap items-center justify-between gap-2">
            <label className={cx('flex cursor-pointer items-center gap-2 text-xs font-semibold', soft)}>
              <input type="checkbox" checked={spoiler} onChange={(e) => setSpoiler(e.target.checked)} className="accent-[#D95743]" />
              Contains spoiler
            </label>
            <span className={cx('text-xs', faint)}>
              {text.length}/{MAX_LEN} · +{replyTo ? 5 : 10} XP
            </span>
          </div>
          {error && <p className="mt-2 text-xs font-semibold text-red-500">{error}</p>}
        </div>
      ) : (
        <div className={cx('mb-2 rounded-[14px] border border-dashed px-5 py-4 text-sm', dark ? 'border-onyx-line' : 'border-line-strong')}>
          <span className={soft}>Want to join the discussion? </span>
          <button type="button" onClick={() => navigate('/account')} className="font-bold text-accent hover:underline">
            Sign in or create a free account
          </button>
          <span className={soft}> to comment, rate, and earn ranks.</span>
        </div>
      )}

      {/* Sort bar */}
      <div className={cx('mt-5 flex items-center gap-1.5 border-y py-2 text-xs font-semibold', dark ? 'border-onyx-line' : 'border-line')}>
        <span className={cx('mr-1', faint)}>Sort by</span>
        {([['top', '👍 Top'], ['new', '🆕 Newest'], ['old', '⏳ Oldest']] as const).map(([k, label]) => (
          <button
            key={k}
            type="button"
            onClick={() => setSort(k)}
            className={cx(
              'rounded-full px-3 py-1 transition-colors',
              sort === k ? 'bg-accent text-white' : cx('hover:text-accent', dark ? 'text-white/60' : 'text-ink-soft'),
            )}
          >
            {label}
          </button>
        ))}
      </div>

      {/* Thread */}
      <div className="mt-5">
        {comments === null ? (
          <p className={cx('text-sm', faint)}>
            {activatedThread === threadKey ? 'Loading comments…' : 'Comments load as you reach this section.'}
          </p>
        ) : comments.length === 0 ? (
          <p className={cx('text-sm', soft)}>No comments yet — be the first to share what you think.</p>
        ) : (
          <ul className="space-y-6">{visible.map(({ c, replies }) => renderComment(c, replies))}</ul>
        )}
      </div>
    </section>
  )
}
